const spanish = new Map(textPairs.map(pair=>{
  const split=pair.lastIndexOf('|');
  return [pair.slice(0,split),pair.slice(split+1)];
}));

const patterns = [
  [/^([\d,.]+) homes?$/, (_,n)=>n+(n==='1'?' vivienda':' viviendas')],
  [/^([\d,.]+) homes\. Zoom to explore$/,(_,n)=>n+' viviendas. Acércate para explorar'],
  [/^([\d,.]+) schools\. Zoom to explore$/,(_,n)=>n+' escuelas. Acércate para explorar'],
  [/^([\d,.]+) homes here$/,(_,n)=>n+' viviendas aquí'],
  [/^Search for “(.+)”$/,(_,q)=>'Búsqueda de «'+q+'»'],
  [/^([\d,.]+) records? matching “(.+)”$/,(_,n,q)=>n+' registros que coinciden con «'+q+'»'],
  [/^([\d,.]+) records? in the Miami index$/,(_,n)=>n+' registros en el índice de Miami'],
  [/^([\d,.]+) records?$/,(_,n)=>n+(n==='1'?' registro':' registros')],
  [/^([\d,.]+) properties ready to search\.$/,(_,n)=>n+' propiedades disponibles para buscar.'],
  [/^Page ([\d,.]+) of ([\d,.]+)$/,(_,page,n)=>'Página '+page+' de '+n],
  [/^Showing ([\d,.]+[–-][\d,.]+)$/,(_,range)=>'Mostrando '+range],
  [/^View all ([\d,.]+) propert(?:y|ies) in this search\.$/,(_,n)=>'Ver todos los resultados de esta búsqueda ('+n+').'],
  [/^([\d,.]+) (beds|baths|sq ft|in-app photos|drone photos)$/,(_,n,label)=>n+' '+({'beds':n==='1'?'dormitorio':'dormitorios','baths':n==='1'?'baño':'baños','sq ft':'pies²','in-app photos':'fotos en la aplicación','drone photos':'fotos de dron'}[label])],
  [/^([\d,.]+) ft²$/,(_,n)=>n+' pies²'],
  [/^more property facts$/i,()=>'más datos de la propiedad'],
  [/^From (.+)$/,(_,address)=>'Desde '+address],
  [/^Email draft to (.+)$/,(_,address)=>'Borrador dirigido a '+address],
  [/^Service from this address to (.+) hasn’t been confirmed in this app\.$/,(_,school)=>'El servicio desde esta dirección hasta '+school+' aún no se ha confirmado en esta aplicación.'],
  [/^Buggy confirmed service from this address to (.+) on (.+)\. Ask about available seats and pickup times\.$/,(_,school,date)=>'Buggy confirmó el servicio desde esta dirección hasta '+school+' el '+date+'. Consulta los cupos y horarios de recogida.'],
  [/^([\d,.]+) searchable records, including ([\d,.]+) disclosed single-family properties in the City of Miami\. County data retrieved (.+)\. This collection also includes the earlier Miami-area listing archive\. ([\d,.]+) additional Miami-Dade homes have a county-matched listing gallery\.$/,(_,n,m,date,more)=>n+' registros disponibles, entre ellos '+m+' viviendas unifamiliares con dirección pública en la ciudad de Miami. Datos del condado consultados el '+date+'. La colección incluye anuncios archivados y otras '+more+' viviendas de Miami-Dade con galerías verificadas.'],
  [/^([\d,.]+) searchable records, including ([\d,.]+) disclosed single-family properties in the City of Miami\. County data retrieved (.+)\. This collection also includes the earlier Miami-area listing archive\.$/,(_,n,m,date)=>n+' registros disponibles, entre ellos '+m+' viviendas unifamiliares con dirección pública en la ciudad de Miami. Datos del condado consultados el '+date+'. La colección también incluye anuncios archivados del área de Miami.'],
  [/^Open ([\d,.]+) drone photos$/,(_,n)=>'Abrir '+n+' fotos de dron'],
  [/^Expand photo (\d+) of (\d+), (.+)$/,(_,n,total,title)=>'Ampliar la foto '+n+' de '+total+', '+phrase(title)],
  [/^Photo (\d+) of (\d+)$/,(_,n,m)=>'Foto '+n+' de '+m],
  [/^County aerial photograph centered on the parcel for (.+)$/,(_,address)=>'Fotografía aérea del condado centrada en la parcela de '+address],
  [/^Aircraft photograph centered on the mapped location of (.+)$/,(_,address)=>'Fotografía aérea centrada en la ubicación de '+address],
  [/^Listing photo tour of (.+)$/,(_,address)=>'Galería del anuncio de '+address],
  [/^([\d,.]+) propert(?:y|ies) with (photo galleries|aerial imagery|front & exterior|drone galleries)(?: matching “(.+)”)?$/i,(_,n,kind,term)=>n+' propiedades con '+({'photo galleries':'galerías de fotos','aerial imagery':'imágenes aéreas','front & exterior':'fotos de la fachada y del exterior','drone galleries':'galerías de dron'}[kind.toLowerCase()])+(term?' que coinciden con «'+term+'»':'')],
];
function phrase(source) {
  if(spanish.has(source)) return spanish.get(source);
  for(const [pattern,replacement] of patterns) if(pattern.test(source)) return source.replace(pattern,replacement);
  return source;
}

export function localText(value, language=currentLanguage()) {
  if(language!=='es' || typeof value!=='string' || !value.trim()) return value;
  const src=value.trim();
  let translated=phrase(src);
  if(translated===src && src.includes(' · ')) translated=src.split(' · ').map(phrase).join(' · ');
  return translated===src ? value : value.replace(src,()=>translated);
}

const savedText=new WeakMap();
const fields=['aria-label','title','placeholder','alt'];
const excluded='script,style,noscript,template,textarea,[data-own-language],[translate="no"]';
const preferenceKey='buggy-atlas-language';
let active='en';
let observer;
export const currentLanguage = () => active;

function chooseLanguage() {
  if(typeof window==='undefined') return 'en';
  const url=new URL(location.href).searchParams.get('lang');
  if(url==='en'||url==='es') return url;
  let saved;
  try { saved=localStorage.getItem(preferenceKey); } catch {}
  if(saved==='en'||saved==='es') return saved;
  return /^es(?:-|$)/i.test(navigator.language || '')?'es':'en';
}
function update(node, key, visible, assign) {
  if(!visible) return;
  const prior=savedText.get(node);
  const previous=prior?.get(key);
  const source=previous && previous.rendered===visible ? previous.source : visible;
  const rendered=localText(source);
  if(source===rendered && !previous) return;
  if(rendered!==visible) assign(rendered);
  if(rendered===source) { prior?.delete(key); return; }
  const record=prior || new Map();
  record.set(key,{source,rendered});
  if(!prior) savedText.set(node,record);
}

function translateLink(element) {
  if(element.tagName!=='A' || element.hasAttribute('download')) return;
  const href=element.getAttribute('href');
  if(!href || href.startsWith('#')) return;
  let target;
  try {target=new URL(href,location.href);} catch {return;}
  if(target.origin!==location.origin || target.pathname!==location.pathname && !target.pathname.endsWith('/buggy/') && !target.pathname.includes('/buggy/service/')) return;
  if(active==='es' && !target.searchParams.has('lang')) target.searchParams.set('lang','es');
  else if(active==='en' && target.searchParams.get('lang')==='es') target.searchParams.delete('lang');
  else return;
  element.setAttribute('href',target.pathname+target.search+target.hash);
}

function translateNode(node) {
  if(node.nodeType===3) {
    if(!node.parentElement?.closest(excluded)) update(node,'text',node.nodeValue,v=>{node.nodeValue=v;});
    return;
  }
  if(node.nodeType!==1||node.matches(excluded)||node.closest(excluded)) return;
  for(const key of fields) if(node.hasAttribute(key)) update(node,key,node.getAttribute(key),v=>node.setAttribute(key,v));
  translateLink(node);
}

export function translate(root=globalThis.document) {
  if(!root) return;
  if(root.nodeType===3) {translateNode(root);return;}
  if(root.nodeType===1 && root.closest(excluded)) return;
  if(root.nodeType===1) translateNode(root);
  const doc=root.ownerDocument || root;
  const walker=doc.createTreeWalker(root,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT,{
    acceptNode:node=>node.nodeType===1 && node.matches(excluded)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT
  });
  while(walker.nextNode()) translateNode(walker.currentNode);
}

function applyPreference(language) {
  active=language;
  document.documentElement.lang=active;
  translate(document);
}

export function setupLanguage() {
  if(typeof document==='undefined') return active;
  const selected=chooseLanguage();
  if(!observer) {
    active=selected;
    document.documentElement.lang=active;
    if(active==='es') translate(document);
    observer=new MutationObserver(records=>{
      if(active==='en') return;
      const roots=new Set();
      for(const change of records) {
        if(change.type==='childList') for(const node of change.addedNodes) roots.add(node);
        else if(change.type==='characterData'||change.type==='attributes') roots.add(change.target);
      }
      for(const node of roots) if(node.isConnected) translate(node);
    });
    observer.observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:[...fields,'href']});
  } else if(selected!==active) applyPreference(selected);
  return active;
}

export function withLanguage(params) {
  const result=new URLSearchParams(params);
  if(active==='es') result.set('lang','es');
  else result.delete('lang');
  return result;
}

export function setLanguage(language) {
  if(language!=='en'&&language!=='es') return active;
  try { localStorage.setItem(preferenceKey,language); } catch {}
  const url=new URL(location.href);
  url.searchParams.set('lang',language);
  history.replaceState(history.state,'',url);
  if(language!==active) {
    applyPreference(language);
    window.dispatchEvent(new CustomEvent('buggy-language-change',{detail:{language}}));
  }
  return active;
}
